from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
left_wheel = Motor(Port.C, Direction.COUNTERCLOCKWISE)
right_wheel = Motor(Port.D, Direction.CLOCKWISE)
drive_base = DriveBase(left_wheel, right_wheel, 56, 128)
back_motor = Motor(Port.A, Direction.COUNTERCLOCKWISE)
front_motor = Motor(Port.E, Direction.CLOCKWISE)
color_sensor = ColorSensor(Port.B)
color_sensor_2 = ColorSensor(Port.F)


# The main program starts here.
drive_base.use_gyro(True)
drive_base.settings(straight_speed=300)
left_wheel.control.limits(acceleration=2500)
right_wheel.control.limits(acceleration=2500)
drive_base.straight(340)
drive_base.straight(-100)
drive_base.straight(100)
drive_base.straight(-340)
drive_base.settings(straight_speed=300)
drive_base.straight(30)
drive_base.turn(90)
drive_base.straight(730)
drive_base.settings(straight_speed=500)
drive_base.straight(-750)
